  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 5, $j$2.1 Figurative Language$j$, $j${"readings": [{"title": "Psalm 1 (King James Version)", "url": "/portal/bible/Psalms/1"}], "body": "Figurative language uses words in a way that goes beyond their literal meaning to create a picture, a feeling or a connection. Learn these four common types, each shown with a verse from the King James Version:\n\nSimile compares two unlike things using like or as. \"All we like sheep have gone astray\" (Isaiah 53:6).\n\nMetaphor says one thing is another. \"The LORD is my shepherd\" (Psalm 23:1).\n\nPersonification gives human actions to something that is not human. \"Let the floods clap their hands: let the hills be joyful together\" (Psalm 98:8).\n\nHyperbole is deliberate exaggeration for effect. \"All the night make I my bed to swim; I water my couch with my tears\" (Psalm 6:6).\n\nFigurative language shapes mood, the feeling a text creates in the reader. A storm described as an angry crowd makes us tense. Rain described as a soft blessing makes us calm.\n\nRead Psalm 1 in the King James Version. Verse 3 says the righteous \"shall be like a tree planted by the rivers of water, that bringeth forth his fruit in his season.\"\n\nYour task: (1) Label each of the four examples above by type. (2) Write one original simile and one original metaphor about a classroom. (3) Explain in one or two sentences what feeling the tree in Psalm 1:3 creates and why.\n\nFlorida standards: ELA.10.R.3.1, ELA.10.V.1.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.10.R.3.1, ELA.10.V.1.3", "script": "Listen, writers are painters, and their paint is words. Today we learn the colors, and they are called figurative language.\n\nFigurative language means using words beyond their plain, literal meaning. If I say, I am so hungry I could eat a horse, I do not plan to eat a horse. I am using a figure to show how strong the feeling is.\n\nLet us learn four common types. First, the simile. A simile compares two unlike things using the word like or as. Isaiah wrote, All we like sheep have gone astray. We are not sheep, but the comparison shows how easily people wander.\n\nSecond, the metaphor. A metaphor says one thing is another thing, with no like or as. The LORD is my shepherd. David does not say the LORD is like a shepherd. He says the LORD is his shepherd, and that makes the picture stronger.\n\nThird, personification. This gives human actions to something that is not human. Psalm ninety eight says, Let the floods clap their hands: let the hills be joyful together. Floods do not have hands, but the poet makes creation join in the celebration.\n\nFourth, hyperbole. This is deliberate exaggeration for effect. In Psalm six, David says, All the night make I my bed to swim; I water my couch with my tears. His bed is not floating, but we feel the depth of his sorrow.\n\nNow watch this. Why do authors use these tools? Because they create mood. Mood is the feeling a text creates in the reader. If a storm is described as an angry crowd pounding on the windows, you feel tension. If rain is described as a soft blessing on the roof, you feel peace. Same weather, different mood, because of the figure of speech.\n\nLook at Psalm one in the King James Version. The righteous person shall be like a tree planted by the rivers of water, that bringeth forth his fruit in his season. That simile gives a feeling of steadiness, nourishment and growth. The tree does not struggle. It is rooted near a river.\n\nA tip. Do not use too many figures at once. One strong comparison beats five weak ones. And avoid worn out phrases. Create something fresh.\n\nYour task today. Label the four examples. Write one original simile and one metaphor about a classroom. Then explain the feeling of the tree in Psalm one and why. Take the four question check when you finish.\n\nLanguage is a gift from God. Use it with care and imagination. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.1 Figurative Language$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 6, $j$2.2 Mood, Tone and Word Choice$j$, $j${"readings": [{"title": "Psalm 121 (King James Version)", "url": "/portal/bible/Psalms/121"}], "body": "Mood is the feeling a text creates in the reader. Tone is the attitude of the author or speaker toward the subject. Authors build both through word choice, imagery, figurative language and rhythm.\n\nWords carry two kinds of meaning. The denotation is the dictionary definition. The connotation is the feelings and ideas attached to the word. House and home both name a place to live, but home carries warmth and belonging. Slender and skinny both describe a thin body, but slender sounds kind and skinny sounds harsh.\n\nRead this original passage:\n\nThe hallway smelled of old chalk and rain. Lockers stood in a long gray row, and every door seemed to be holding its breath. At the far end, one light buzzed and flickered, as if it could not decide whether to stay.\n\nRead Psalm 121 in the King James Version. The words \"I will lift up mine eyes unto the hills, from whence cometh my help\" (Psalm 121:1) create a mood of hope and trust.\n\nYour task: (1) Name the mood of the hallway passage and two words or details that create it. (2) Rewrite the first two sentences to create a cheerful mood by changing the word choice. (3) Give the denotation of house and a connotation of home.\n\nFlorida standards: ELA.10.R.3.1, ELA.10.V.1.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.10.R.3.1, ELA.10.V.1.3", "script": "Now, let us talk about feeling. When you read a story, you feel something before you can explain why. That feeling is called mood.\n\nMood is the feeling a text creates in the reader. Tone is different. Tone is the attitude of the author or the speaker toward the subject. A teacher can speak in a warm tone, a stern tone or a playful tone, even while teaching the same lesson. Mood is what you, the reader, feel. Tone is how the writer sounds.\n\nHow do authors build mood and tone? Through word choice, imagery, figurative language and rhythm. Let us focus on word choice, because each word carries two kinds of meaning.\n\nThe first is the denotation. That is the dictionary definition. The second is the connotation. That is the feelings and ideas attached to the word. House and home both name a place to live. But home carries warmth, family and belonging. House is only a building. Slender and skinny both describe a thin body, but slender sounds kind and skinny sounds harsh. Choosing the right word changes the feeling.\n\nWatch this. Here is an original passage. The hallway smelled of old chalk and rain. Lockers stood in a long gray row, and every door seemed to be holding its breath. At the far end, one light buzzed and flickered, as if it could not decide whether to stay.\n\nWhat is the mood? Uneasy, quiet, waiting. Which words create it? Gray, holding its breath, buzzed, flickered, could not decide. Notice the personification. Doors do not breathe, and a light does not decide. Those figures make the hallway feel alive and anxious.\n\nNow imagine changing a few words. The hallway smelled of fresh paint and sunshine. Lockers stood in a bright row, and every door seemed ready to welcome us. The place is the same, but the mood is now cheerful. That is the power of word choice.\n\nLook at Scripture. In Psalm one hundred twenty one, the writer says, I will lift up mine eyes unto the hills, from whence cometh my help. My help cometh from the LORD, which made heaven and earth. The words lift up, hills and help build a mood of hope and trust.\n\nYour task today. Name the mood of the hallway passage and two words that create it. Rewrite the first two sentences to make a cheerful mood. Then give the denotation of house and a connotation of home. Take the four question check when you finish.\n\nChoose your words the way a builder chooses stones. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.2 Mood, Tone and Word Choice$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 7, $j$2.3 Paraphrasing$j$, $j${"readings": [{"title": "Proverbs 3 (King James Version)", "url": "/portal/bible/Proverbs/3"}], "body": "To paraphrase is to restate a passage in your own words while keeping its meaning. A paraphrase is different from a quotation, which uses the exact words, and from a summary, which gives only the main points in a shorter form.\n\nSteps to paraphrase: (1) Read the passage until you understand it. (2) Identify the main ideas. (3) Look away and write the idea in your own words. (4) Compare your version with the original for accuracy. (5) Give credit to the source.\n\nExample from the King James Version: \"Trust in the LORD with all thine heart; and lean not unto thine own understanding. In all thy ways acknowledge him, and he shall direct thy paths\" (Proverbs 3:5 to 6). A paraphrase: Rely completely on God instead of on your own limited understanding, include Him in every decision, and He will make your way clear.\n\nYour task: (1) Paraphrase Proverbs 3:5 to 6 in your own words. (2) Paraphrase this sentence: Although the experiment failed, the students learned why the first design could not hold the weight. (3) Explain in one sentence the difference between a paraphrase and a summary.\n\nFlorida standards: ELA.10.R.3.2, ELA.K12.EE.1.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.10.R.3.2, ELA.K12.EE.1.1", "script": "Listen, one of the most useful skills in school and in life is paraphrasing. It proves you understand what you read.\n\nTo paraphrase is to restate a passage in your own words while keeping its meaning. It is not the same as a quotation. A quotation uses the exact words and puts them in quotation marks. It is also not the same as a summary. A summary gives only the main points and is shorter. A paraphrase usually has about the same length as the original, but the words are your own.\n\nHere are five steps. Step one, read the passage until you truly understand it. If you do not understand it, you cannot restate it. Step two, find the main ideas. Step three, look away from the text and write the idea the way you would explain it to a friend. Step four, compare your version to the original and check that you kept the meaning. Step five, give credit to the source. Changing the words does not make the idea yours.\n\nWatch this. Here is Proverbs chapter three, verses five and six, in the King James Version. Trust in the LORD with all thine heart; and lean not unto thine own understanding. In all thy ways acknowledge him, and he shall direct thy paths. Now a paraphrase. Rely completely on God instead of on your own limited understanding, include Him in every decision, and He will make your way clear. Notice that the meaning is the same. The words are different, and they are easier for a modern reader.\n\nNow a common mistake. Some students only swap a few words. For example, replacing trust with rely and leaving the rest. That is not a true paraphrase. You must change both the words and the structure of the sentence.\n\nLet us try one more. Although the experiment failed, the students learned why the first design could not hold the weight. A paraphrase might say, The test did not work, but the class discovered the reason the first model was too weak. Same meaning, new wording.\n\nA word about honesty. Even when you paraphrase, you must name where the idea came from. Scripture teaches us to be honest in all our dealings, and that includes the way we use other people's work.\n\nYour task today. Paraphrase Proverbs three, verses five and six. Paraphrase the experiment sentence. Then explain the difference between a paraphrase and a summary. Take the four question check when you finish.\n\nTo restate an idea well, you must first understand it well. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.3 Paraphrasing$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 8, $j$2.4 Adapted Mythical, Classical and Religious Texts$j$, $j${"readings": [{"title": "Luke 10 (King James Version)", "url": "/portal/bible/Luke/10"}], "body": "An adaptation retells an older story in a new form, time or setting. Authors adapt mythical stories (traditional tales that explain beliefs or the world), classical works (ancient Greek and Roman writing) and religious texts such as Scripture. An allusion is a brief reference to a well known story or person, such as a Good Samaritan, the Midas touch or an Achilles heel.\n\nWhen you compare an adaptation to its source, ask three questions: What stays the same? What changes? Why did the author make the change?\n\nSource: In Luke 10:33 a Samaritan \"had compassion\" on a wounded stranger, and in verse 37 Jesus says, \"Go, and do thou likewise.\" Read Luke 10:25 to 37 in the King James Version.\n\nRead this original modern retelling:\n\nMarcus was stranded in the parking lot of the bus depot with a flat tire and a dead phone. Two commuters glanced at him and hurried on. Then a night janitor named Mr. Ortiz, who had every reason to be tired, set down his mop, brought a jack from his old truck, and stayed until the job was finished. \"Somebody did that for me once,\" he said.\n\nYour task: (1) Name the original story and one detail the retelling keeps. (2) Name one detail the retelling changes and explain why you think the author changed it. (3) Write one sentence that uses an allusion to a Bible story or a Greek myth.\n\nFlorida standards: ELA.10.R.3.3, ELA.K12.EE.1.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.10.R.3.3, ELA.K12.EE.1.1", "script": "Now, let us talk about stories that never die. The oldest stories in the world keep coming back, wearing new clothes. We call that adaptation.\n\nAn adaptation retells an older story in a new form, a new time or a new setting. Authors adapt three kinds of old texts. Mythical texts are traditional tales that explain beliefs or the world, like the Greek story of Pandora. Classical texts come from ancient Greece and Rome, like the Odyssey. And religious texts, like the Bible, have inspired plays, songs, films and novels for centuries.\n\nWriters also use allusions. An allusion is a brief reference to a well known story or person. When someone says, he was a good Samaritan, we instantly know he helped a stranger. When someone says, she has the Midas touch, we know everything she handles turns to gold. When someone says, that is his Achilles heel, we know it is his one weak spot. A single phrase carries a whole story.\n\nWatch this. Here is the source. In Luke chapter ten, in the King James Version, Jesus tells of a man who fell among thieves. A priest and a Levite passed by on the other side. But a certain Samaritan came where he was, and when he saw him, he had compassion on him. Jesus ends by saying, Go, and do thou likewise.\n\nNow the modern retelling. Marcus is stranded in a parking lot with a flat tire. Two commuters hurry past. A night janitor named Mr. Ortiz stops, brings a jack and stays until the work is done.\n\nWhen you compare an adaptation to its source, ask three questions. What stays the same? Here the stranger in need, the people who pass by, and the one who stops all remain. What changes? The road becomes a parking lot, the wounds become a flat tire, and the Samaritan becomes a tired janitor. Why did the author change it? Possibly to show that mercy still belongs in everyday places, and that the person who helps may be the one we least expect.\n\nNotice also what the retelling adds. Mr. Ortiz says, Somebody did that for me once. That line explains why he helps, and it suggests that kindness is passed from person to person.\n\nYour task today. Name the original story and one detail the retelling keeps. Name one detail it changes and explain why. Then write one sentence using an allusion. Take the four question check when you finish.\n\nOld stories live on because their truth never grows old. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.4 Adapted Mythical, Classical and Religious Texts$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 2, $j$Assessment 2: Create a Mood$j$, $j${"prompt": "Write a descriptive paragraph of 7 to 9 sentences set in a place you choose, such as a church sanctuary at midnight, a kitchen at sunrise, or a stadium after a loss. Create one clear mood.\n\nYour paragraph must include at least one simile, one metaphor and one example of personification. Label each in parentheses after the sentence, for example (simile). Then write 3 to 4 sentences explaining how your word choice, including at least two words with strong connotations, and your figurative language create the mood. Use complete sentences and correct grammar.", "rubric": "100 points. One clear mood is created: 20 points. Simile, metaphor and personification are present, labeled and effective: 30 points. Word choice and connotation: 20 points. Explanation of how the choices create the mood: 20 points. Conventions and organization: 10 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 2: Create a Mood$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 2, $j$Discussion 2: A Story That Keeps Being Retold$j$, $j${"prompt": "Think of an old story that has been retold many times, such as a Bible account, a Greek myth or a fairy tale. Write a post of at least 120 words that (1) names the story, (2) tells one retelling you know, in a film, song, book or sermon, (3) explains what stayed the same and what changed, and (4) gives your reason for why the story still speaks to people today. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Which change in a retelling would you never want to see, and why? Keep your tone kind and your language clean."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 2: A Story That Keeps Being Retold$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 6, $j$Check 2.1: Figurative Language$j$, $j${"questions": [{"q": "A simile compares two things using:", "options": ["The words like or as", "A question mark", "The word because", "A number"]}, {"q": "'The LORD is my shepherd' is an example of:", "options": ["A metaphor", "A simile", "A rhyme", "Hyperbole"]}, {"q": "'Let the floods clap their hands' is:", "options": ["A rhyme scheme", "A simile", "A plain fact", "Personification"]}, {"q": "Hyperbole is:", "options": ["A type of rhyme", "Deliberate exaggeration for effect", "A summary", "A literal statement"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: Figurative Language$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,3,1}'::int[], array[$j$A simile uses like or as.$j$,$j$A metaphor says one thing is another.$j$,$j$It gives human action to floods.$j$,$j$Hyperbole exaggerates on purpose.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: Figurative Language$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 7, $j$Check 2.2: Mood, Tone and Word Choice$j$, $j${"questions": [{"q": "Mood is:", "options": ["The plot summary", "The author's age", "The feeling a text creates in the reader", "The rhyme pattern"]}, {"q": "Tone is:", "options": ["The number of pages", "The title", "The attitude of the author or speaker toward the subject", "The setting only"]}, {"q": "Connotation is:", "options": ["The feelings and ideas attached to a word", "The spelling of a word", "A type of rhyme", "The dictionary definition only"]}, {"q": "Which word has the warmest connotation?", "options": ["Home", "Unit", "Structure", "Dwelling"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Mood, Tone and Word Choice$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,0,0}'::int[], array[$j$Mood is the feeling the reader gets.$j$,$j$Tone is the attitude behind the words.$j$,$j$Connotation is the feeling a word carries.$j$,$j$Home carries warmth and belonging.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Mood, Tone and Word Choice$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 8, $j$Check 2.3: Paraphrasing$j$, $j${"questions": [{"q": "A paraphrase is:", "options": ["An exact copy of the words", "A new idea of your own", "A one word answer", "A restatement in your own words that keeps the meaning"]}, {"q": "A good paraphrase should:", "options": ["Copy every word", "Keep the original meaning", "Leave out the main idea", "Add your own opinion"]}, {"q": "What is a good first step in paraphrasing?", "options": ["Read until you understand the passage", "Copy the passage", "Delete the passage", "Change the title"]}, {"q": "After you paraphrase an idea from a source, you should:", "options": ["Give credit to the source", "Claim the idea as your own", "Hide the source", "Change the author's name"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: Paraphrasing$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,1,0,0}'::int[], array[$j$A paraphrase keeps the meaning in new words.$j$,$j$Meaning must stay the same.$j$,$j$You must understand it before you restate it.$j$,$j$Paraphrased ideas still need credit.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: Paraphrasing$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 9, $j$Check 2.4: Adapted Mythical, Classical and Religious Texts$j$, $j${"questions": [{"q": "An adaptation is:", "options": ["A dictionary entry", "An exact copy with no changes", "A list of characters", "A retelling of an older story in a new form or setting"]}, {"q": "An allusion is:", "options": ["A grammar mistake", "A brief reference to a well known story or person", "A type of poem", "A long summary"]}, {"q": "Someone who has an Achilles heel has:", "options": ["One weak spot", "A strong muscle", "A famous city", "A fast pace"]}, {"q": "When you compare an adaptation to its source, you ask:", "options": ["What color the cover is", "What stays the same, what changes and why", "How many pages it has", "Only who printed it"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Adapted Mythical, Classical and Religious Texts$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,1,0,1}'::int[], array[$j$An adaptation retells a source in a new way.$j$,$j$An allusion points to a known story.$j$,$j$The phrase comes from a Greek myth about a weak spot.$j$,$j$Compare what is kept, what is changed and the reason.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Adapted Mythical, Classical and Religious Texts$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 10, $j$Unit Quiz 2: Figurative Language, Mood and Adapted Texts$j$, $j${"questions": [{"q": "A simile compares two things using:", "options": ["A rhyme", "A number", "A question", "The words like or as"]}, {"q": "A metaphor:", "options": ["Is a summary", "Always uses like or as", "Is an exact quotation", "Says one thing is another"]}, {"q": "Giving human actions to something not human is called:", "options": ["A simile", "A paraphrase", "An allusion", "Personification"]}, {"q": "Mood is:", "options": ["The title", "The feeling a text creates in the reader", "The setting only", "The attitude of the author only"]}, {"q": "Connotation is:", "options": ["A rhyme", "The dictionary definition", "The spelling", "The feelings and ideas attached to a word"]}, {"q": "A paraphrase should:", "options": ["Copy the words exactly", "Keep the meaning in your own words", "Leave out the main idea", "Change the meaning"]}, {"q": "An allusion is:", "options": ["A type of rhyme", "A brief reference to a well known story or person", "A long retelling", "A footnote"]}, {"q": "When comparing an adaptation to its source, you should ask:", "options": ["Who owns the book", "What the cover looks like", "How long the book is", "What stays the same, what changes and why"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: Figurative Language, Mood and Adapted Texts$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,3,3,1,3,1,1,3}'::int[], array[$j$A simile uses like or as.$j$,$j$A metaphor says one thing is another.$j$,$j$That is personification.$j$,$j$Mood is the feeling the reader gets.$j$,$j$Connotation is the feeling a word carries.$j$,$j$A paraphrase keeps the meaning in new words.$j$,$j$An allusion points to a known story.$j$,$j$Compare what is kept, changed and the reason.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: Figurative Language, Mood and Adapted Texts$j$ on conflict (item_id) do nothing;
